<?php
$page_title="Verifikasi pembayaran";include "_header.php";
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$aksi=$_POST['aksi'];$catatan=trim($_POST['catatan']??'');$conn->begin_transaction();try{$s=$conn->prepare("SELECT * FROM pembayaran WHERE id=? FOR UPDATE");$s->bind_param("i",$id);$s->execute();$p=$s->get_result()->fetch_assoc();if(!$p||$p['status']!=='Menunggu')throw new Exception("Pembayaran sudah diproses atau tidak ditemukan.");if($aksi==='setuju'){$ins=$conn->prepare("INSERT INTO voting(user_id,kontestan_id,kategori,pembayaran_id,jumlah_suara) SELECT ?,k.id,k.kategori,?,? FROM kontestan k WHERE k.id=?");$ins->bind_param("iiii",$p['user_id'],$id,$p['jumlah_suara'],$p['kontestan_id']);if(!$ins->execute())throw new Exception("Gagal memasukkan suara. Pemilih mungkin sudah memiliki suara di kategori tersebut.");$status='Disetujui';}else{$status='Ditolak';} $up=$conn->prepare("UPDATE pembayaran SET status=?,catatan_admin=?,diverifikasi_pada=NOW() WHERE id=?");$up->bind_param("ssi",$status,$catatan,$id);$up->execute();$conn->commit();flash("Pembayaran berhasil diproses.");}catch(Throwable $e){$conn->rollback();flash($e->getMessage(),"danger");}redirect("pembayaran.php");}
$q=$conn->query("SELECT p.*,u.nama nama_pemilih,u.email,k.nama nama_kontestan,k.kategori FROM pembayaran p JOIN users u ON u.id=p.user_id JOIN kontestan k ON k.id=p.kontestan_id ORDER BY FIELD(p.status,'Menunggu','Disetujui','Ditolak'),p.id DESC");
?>
<div class="panel p-3 p-md-4"><div class="table-responsive"><table class="table"><thead><tr><th>Pemilih / Kontestan</th><th>Jumlah</th><th>Total</th><th>Bukti</th><th>Status / tindakan</th></tr></thead><tbody><?php while($r=$q->fetch_assoc()):?><tr><td><strong><?=e($r['nama_pemilih'])?></strong><div class="small-muted"><?=e($r['email'])?></div><div class="mt-1"><?=e($r['nama_kontestan'])?> <span class="tag"><?=e($r['kategori'])?></span></div></td><td><?=$r['jumlah_suara']?></td><td>Rp <?=number_format($r['total_bayar'],0,',','.')?></td><td><a target="_blank" href="../<?=e($r['bukti'])?>">Lihat bukti</a></td><td><span class="badge text-bg-<?=$r['status']==='Disetujui'?'success':($r['status']==='Ditolak'?'danger':'warning')?>"><?=e($r['status'])?></span><?php if($r['status']==='Menunggu'):?><form method="post" class="mt-2"><input type="hidden" name="id" value="<?=$r['id']?>"><input class="form-control form-control-sm mb-1" name="catatan" placeholder="Catatan (opsional)"><button class="btn btn-success btn-sm" name="aksi" value="setuju">Setujui</button> <button class="btn btn-outline-danger btn-sm" name="aksi" value="tolak" data-confirm="Tolak pembayaran ini?">Tolak</button></form><?php elseif($r['catatan_admin']):?><div class="small-muted"><?=e($r['catatan_admin'])?></div><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div>
<?php include "_footer.php"; ?>